var i=[{title:`Зусилля і шкода`,text:`М’язова втома, важке дихання та тимчасове печіння можуть супроводжувати інтенсивні вправи. Різкий біль, новий дискомфорт у суглобі, біль, що поширюється, чи запаморочення не є досягненнями. Ваше тіло адаптується, коли за важким, але переносимим тренуванням іде достатнє відновлення. Біль не є тим, що змушує це працювати.`},{title:`Болючість: поганий показник`,text:`Відстрочений біль у м’язах особливо поширений після незнайомих чи важких вправ. Він часто згасає, коли тіло звикає до руху, тоді як ваша сила та форма продовжують покращуватися. Заняття, що лишає вас ледь болючим, усе одно може бути продуктивним, а надто сильна болючість може ускладнювати регулярні тренування.`},{title:`Прогрес без покарання`,text:`Обирайте повторення, що є викликом, але контрольовані, поступово підвищуйте тренувальні вимоги та включайте відпочинок чи легші дні. Завершення підходу з кількома повтореннями в запасі може бути розумним. Дослідження не показують, що середньому здоровому дорослому потрібно знову й знову доходити до миттєвої м’язової відмови, щоб отримати вартісні результати.`},{title:`Приклад`,text:`Початківець, що робить два заняття на все тіло на тиждень і стабільно додає повторення в присідах і віджиманнях, може прогресувати, не відчуваючи себе розбитим після кожного заняття.`},{title:`Як це працює в TrainUp`,text:`Після тренування ви оцінюєте зусилля заняття (RPE) і повідомляєте про будь-який біль із зазначенням ділянки тіла та вправи. Якщо щось болить під час тренування, використайте «У мене біль», щоб негайно завершити вправу; вона лишається поза вашими планами, доки ви не відновите її з Профілю. Будь-який нещодавній біль означає, що ваш наступний план не стане важчим. Новий чи сильний біль є причиною зупинитися і пройти оцінку.`}];var l=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Практичні рекомендації ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: біль у суглобах`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var n={sections:i,sources:l};export{n as default,i as sections,l as sources};